/// One period of sin starting at `start` radians: N entries plus a guard
/// point. Built from std::sin in double at startup.
template<typename T, std::size_t N>
inline auto make_sin_table(double start) -> std::array<T, N + 1>
{
    auto t = std::array<T, N + 1>{};
    for (std::size_t i = 0; i <= N; ++i) {
        t[i] = static_cast<T>(std::sin(start + 2.0 * std::numbers::pi * static_cast<double>(i) / static_cast<double>(N)));
    }
    return t;
}

/// sin(-pi + 2 pi i / N), for radians lookups.
template<typename T, std::size_t N>
inline const auto sin_table = make_sin_table<T, N>(-std::numbers::pi);

/// sin(2 pi i / N), for phase-accumulator lookups.
template<typename T, std::size_t N>
inline const auto sin_turns_table = make_sin_table<T, N>(0.0);

/// sin(x) on [-pi, pi], Taylor degree 13: x * P(x^2).
template<typename T>
inline auto taylor_sin_13(T x) -> T
{
    const auto x2 = x * x;
    auto p = T(1.6059043836821613e-10);
    p = p * x2 + T(-2.505210838544172e-08);
    p = p * x2 + T(2.7557319223985893e-06);
    p = p * x2 + T(-0.0001984126984126984);
    p = p * x2 + T(0.008333333333333333);
    p = p * x2 + T(-0.16666666666666666);
    p = p * x2 + T(1.0);
    return x * p;
}

/// sin(x) on [-pi, pi], Padé [7/6]: x * P(x^2) / Q(x^2).
template<typename T>
inline auto pade_sin_7_6(T x) -> T
{
    const auto x2 = x * x;
    auto p = T(-4.163277313164616e-05);
    p = p * x2 + T(0.0045855159115865355);
    p = p * x2 + T(-0.14252345450692558);
    p = p * x2 + T(1.0);
    auto q = T(1.5950358737736648e-06);
    q = q * x2 + T(0.00027605127154338275);
    q = q * x2 + T(0.024143212159741086);
    q = q * x2 + T(1.0);
    return x * p / q;
}

/// sin(x) on [-pi, pi], 1024-entry table, nearest lookup.
template<typename T>
inline auto lut_sin_nearest_1024(T x) -> T
{
    constexpr auto pi = T(3.141592653589793);
    constexpr auto scale = T(162.97466172610083);  // N / 2pi
    const auto& t = sin_table<T, 1024>;
    const auto pos = (x + pi) * scale;
    const auto i = static_cast<std::uint32_t>(static_cast<std::int32_t>(pos + T(0.5)) & 1023);
    return t[i];
}

/// sin(x) on [-pi, pi], 1024-entry table, linear lookup.
template<typename T>
inline auto lut_sin_linear_1024(T x) -> T
{
    constexpr auto pi = T(3.141592653589793);
    constexpr auto scale = T(162.97466172610083);  // N / 2pi
    const auto& t = sin_table<T, 1024>;
    const auto pos = (x + pi) * scale;
    const auto fl = std::floor(pos);
    const auto frac = pos - fl;
    const auto i = static_cast<std::uint32_t>(static_cast<std::int32_t>(fl) & 1023);
    return t[i] + frac * (t[i + 1] - t[i]);
}

