/// cheb_turns_sin_13 fed from a 32-bit phase accumulator: x = phase / 2^32.
/// Converting to f32 keeps 24 bits of phase, so near the zeros at 1/2 and 1
/// the input itself only has absolute precision -- same as any table.
template<typename T>
inline auto cheb_turns_phase_sin_13(std::uint32_t phase) -> T
{
    return cheb_turns_sin_13<T>(static_cast<T>(phase) * T(2.3283064365386963e-10));
}

/// sin(2 pi phase / 2^32) from a 32-bit phase accumulator, Chebyshev degree 13.
/// x, x - 1 and u = x - 1/2 each come straight from the integer, so all three
/// zeros keep full relative precision (cf. cheb_turns_phase, which converts once).
template<typename T>
inline auto cheb_phase_sin_13(std::uint32_t phase) -> T
{
    constexpr auto s = T(2.3283064365386963e-10);  // 2^-32
    const auto x = static_cast<T>(phase) * s;
    const auto xm1 = -static_cast<T>(std::uint32_t{0} - phase) * s;
    const auto u = static_cast<T>(static_cast<std::int32_t>(phase - 0x80000000u)) * s;
    const auto u2 = u * u;
    auto p = T(3.161601856720294);
    p = p * u2 + T(-14.049663725541881);
    p = p * u2 + T(38.49587885367295);
    p = p * u2 + T(-67.07662737709583);
    p = p * u2 + T(64.83582285642966);
    p = p * u2 + T(-25.132741155387375);
    return -u * x * xm1 * p;
}

